ValidationRule.errorConditionFormula:
AND(
    NOT( 
    $Setup.PMC_ProcessSwitches__c.PMC_BypassValidationRule__c 
    ),
    AND(
        Account.RecordType.DeveloperName == 'PMC_SS_Customer',
        OR(
            ISPICKVAL(Account.Type, 'Ship-to'),
            ISPICKVAL(Account.Type, 'Bill-to'),
            ISPICKVAL(Account.Type, 'Payer')
        )
    )
)
